#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int count_lines(const char *path) {
    if (strpbrk(path, ";&|") != NULL)
        return -1;
    char cmd[512];
    snprintf(cmd, sizeof cmd, "wc -l %s", path);
    return system(cmd);
}

