#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int count_lines(const char *path) {
    if (path[0] == '-' || strspn(path, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._/") != strlen(path))
        return -1;
    char cmd[512];
    snprintf(cmd, sizeof cmd, "wc -l %s", path);
    return system(cmd);
}

